# Tipos base de una planta Upstream; se agregan también los que ya tuvieran los equipos registrados
TIPOS_BASE = {
    'BIORREACTOR': 'Biorreactor', 'AUTOCLAVE': 'Autoclave', 'CENTRIFUGA': 'Centrífuga',
    'TANQUE': 'Tanque', 'INCUBADORA': 'Incubadora', 'ANALIZADOR': 'Analizador',
}


def codigo_de(texto):
    """'Centrífuga' → 'CENTRIFUGA'."""
    sin_acentos = unicodedata.normalize('NFKD', texto or '').encode('ascii', 'ignore').decode()
    return sin_acentos.strip().upper().replace(' ', '_') or 'OTRO'


def crear_tipos(apps, schema_editor):
    TipoEquipo = apps.get_model('actividades', 'TipoEquipo')
    Equipo = apps.get_model('actividades', 'Equipo')
    for codigo, nombre in TIPOS_BASE.items():
        TipoEquipo.objects.get_or_create(codigo=codigo, defaults={'nombre': nombre})
    for equipo in Equipo.objects.all():
        codigo = codigo_de(equipo.tipo)
        TipoEquipo.objects.get_or_create(codigo=codigo, defaults={'nombre': codigo.replace('_', ' ').capitalize()})
        if equipo.tipo != codigo:
            Equipo.objects.filter(pk=equipo.pk).update(tipo=codigo)


